import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const resources = { geometries: [], materials: [], textures: [] };

  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;
  resources.textures.push(texture);

  // Create background plane
  const planeGeometry = new THREE.PlaneGeometry(5.12, 3.2);
  const planeMaterial = new MeshBasicNodeMaterial({ map: texture, side: THREE.DoubleSide });
  resources.geometries.push(planeGeometry);
  resources.materials.push(planeMaterial);
  group.add(new THREE.Mesh(planeGeometry, planeMaterial));

  // Create MSDF text
  if (ctx.fontAtlas?.createText) {
    const textMesh = ctx.fontAtlas.createText({
      text: config.textContent || 'Pricing',
      font: 'Lora',
      fontSize: 0.34,
      fontWeight: 400,
      color: 0x16161d,
      anchorX: 'center',
      anchorY: 'middle',
    });

    if (textMesh && textMesh instanceof THREE.Object3D) {
      textMesh.position.z = 0.1;
      group.add(textMesh);
      if (textMesh.geometry) resources.geometries.push(textMesh.geometry);
      if (textMesh.material) resources.materials.push(textMesh.material);
    }
  }

  // Apply cinematicPrimitives
  if (config.cinematicPrimitives?.length) {
    config.cinematicPrimitives.forEach(p => {
      ctx.primitives?.[p.name]?.(group, p.params);
    });
  }

  // Apply scene transforms
  const pos = config.scenePosition || {};
  group.position.set(pos.x ?? 0, pos.y ?? 3, pos.z ?? 0);
  if (pos.rotationXYZ) group.rotation.set(...pos.rotationXYZ);
  if (pos.scaleXYZ) group.scale.set(...pos.scaleXYZ);

  // Cleanup
  group.userData.cleanup = () => {
    resources.geometries.forEach(g => g?.dispose?.());
    resources.materials.forEach(m => m?.dispose?.());
    resources.textures.forEach(t => t?.dispose?.());
  };

  group.userData.handlers = {};

  return group;
}
